from datetime import datetime
from decimal import Decimal

from .errors import BillingError
from .money import ZERO, round_money, to_money

CAMPAIGNS = {"black-friday": {"percent": 30, "ends": datetime(2025, 12, 1)}}

HUNDRED = Decimal("100")


def campaign_percent(name: str, now: datetime | None = None) -> int:
    campaign = CAMPAIGNS.get(name)
    if campaign is None:
        raise ValueError(f"unknown campaign {name!r}")
    now = now or datetime.now()
    return campaign["percent"] if now < campaign["ends"] else 0


def bulk_discount_percent(quantity: int) -> int:
    if quantity < 0:
        raise ValueError("quantity must be non-negative")
    if quantity >= 50:
        return 10
    return 5 if quantity >= 10 else 0


def _to_percent(percent) -> Decimal:
    """Validate a percentage without going through a float path."""
    if isinstance(percent, bool) or isinstance(percent, float):
        raise BillingError("invalid_percent", repr(percent))
    if isinstance(percent, Decimal):
        value = percent
    elif isinstance(percent, int):
        value = Decimal(percent)
    else:
        raise BillingError("invalid_percent", repr(percent))
    if value < ZERO or value > HUNDRED:
        raise BillingError("invalid_percent", repr(percent))
    return value


def apply_discount(amount, percent):
    """``amount`` reduced by ``percent`` percent (15 means 15% off)."""
    amount = to_money(amount)
    rate = _to_percent(percent)
    discounted = amount * (HUNDRED - rate) / HUNDRED
    return round_money(discounted)
